mapper.select:
select run_id, skill_id, skill_version, audience_id, audience_name, customer_count,
       status, blocked_reason, duration_ms, operator_id, operator_name, trace_id, create_time
from tl_skill_run

    and skill_id = #{skillId}
    and audience_id = #{audienceId}
    and status = #{status}
    and operator_id = #{operatorId}
    and create_time >= #{params.beginTime}
    and create_time <= #{params.endTime}

order by create_time desc, run_id desc
